body:has(.wpe-ess-hero, .wpe-ess-page-hero--docs) .wpe-ess-header .wpe-ess-logo__text small { color: #a4a8b4; }
body:has(.wpe-ess-hero, .wpe-ess-page-hero--docs) .wpe-ess-header :is(.current-menu-item > a, .current-menu-item > .wp-block-navigation-item__content, .wpe-menu__desktop a:hover) { background: #fff; color: #0b1a3d; }
body:has(.wpe-ess-hero, .wpe-ess-page-hero--docs) .wpe-ess-header :is(.wp-block-search__button, .wpe-search__submit, .wpe-mini-cart__toggle, .wpe-mini-cart > a, .wpe-mini-cart > button) { background: rgba(255,255,255,.08) !important; color: #fff; }

/* Footer (Figma) */
.wpe-ess-footer { background: var(--wp--preset--color--ink); color: var(--wp--preset--color--on-ink-muted); padding: clamp(48px, 5vw, 96px) clamp(20px, 6.25vw, 120px) 40px; }
.wpe-ess-news { border-radius: 28px; padding: clamp(24px, 2.3vw, 44px) clamp(24px, 2.5vw, 48px); background: linear-gradient(110deg, #1f48a6, #2f6be0); border: 1px solid rgba(255,255,255,.08); gap: 24px; color: #fff; }
.wpe-ess-news .wpe-ess-over { color: #ec7d1a; }
.wpe-ess-news .wpe-ess-band__title { color: #fff; font-size: 32px !important; line-height: 38px; }
.wpe-ess-news .wpe-ess-band__text { color: #a9b6d3; font-size: 15px; }
.wpe-newsletter { display: flex; gap: 6px; padding: 6px 6px 6px 18px; border-radius: 999px; background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.18); min-width: min(100%, 380px); }
.wpe-newsletter input[type=email] { flex: 1; border: 0; background: transparent; color: #fff; font: inherit; font-size: 14px; outline: 0; min-width: 0; }
.wpe-newsletter input[type=email]::placeholder { color: var(--wp--preset--color--on-ink-muted); }
.wpe-newsletter button { border: 0; border-radius: 999px; padding: 10px 18px; background: linear-gradient(90deg, #E8701A, #F7A23E); color: var(--wp--preset--color--ink); font-weight: 700; cursor: pointer; }
.wpe-ess-foot__cols { margin-top: 72px !important; gap: 48px; }
.wpe-ess-foot__about { font-size: 15px; line-height: 24px; max-width: 340px; margin: 20px 0; }
.wpe-ess-foot__small { font-size: 13px; margin: 20px 0 0; }
.wpe-ess-foot__h { color: #fff; font-size: 14px !important; font-family: var(--wp--preset--font-family--body); font-weight: 600; margin: 0 0 14px; }
.wpe-ess-foot__list { list-style: none; padding: 0; margin: 0; }
.wpe-ess-foot__list li { margin: 0 0 14px; font-size: 15px; line-height: 24px; }
.wpe-ess-foot__list a, .wpe-ess-foot__legal a { color: var(--wp--preset--color--on-ink-muted); text-decoration: none; }
.wpe-ess-foot__list a:hover, .wpe-ess-foot__legal a:hover { color: #fff; }
.wpe-ess-foot__bottom { margin-top: 72px !important; padding-top: 28px; border-top: 1px solid rgba(255,255,255,.1); font-size: 13px; }
.wpe-ess-foot__bottom p { margin: 0; }
.wpe-ess-foot__bottom strong { color: #fff; font-weight: 600; }
.wpe-ess-foot__legal { display: flex; gap: 18px; }
.wpe-ess-social { display: flex; gap: 8px; margin: 0; }
