.wpe-ess-stepper section.wpe-forms { max-width: none !important; width: 100% !important; --wpek-content-width: 100%; } .wpe-ess-stepper .wpe-steps__foot { width: 100%; }
.wpe-ess-stepper .wpe-steps__foot { display: flex !important; justify-content: space-between !important; } .wpe-ess-stepper .wpe-steps__foot .wpe-steps__next { margin-left: auto !important; } .wpe-ess-stepper .wpe-steps__bar { display: block !important; height: 4px !important; width: 100% !important; margin: 0 0 26px !important; } .wpe-ess-stepper .wpe-steps__bar span { display: block !important; height: 4px !important; }
.wpe-ess-tag--improved { background: #e9eef9; color: #1f48a6; }

/* Figma 13: stats + logos, team beside the map */
.wpe-ess-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; }
